"""Bounded snapshot lifetimes with generated bytes and concurrent leases."""
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
import tempfile
import threading
import unittest
from unittest.mock import patch

from page_cache import SourcePageCache


class PageSnapshotTests(unittest.TestCase):
    def setUp(self):
        root = Path(__file__).resolve().parents[1] / 'work' / 'page-cache-tests'
        root.mkdir(parents=True, exist_ok=True)
        temporary = tempfile.TemporaryDirectory(dir=root)
        self.addCleanup(temporary.cleanup)
        self.cache = SourcePageCache(temporary.name, max_bytes=8, max_entries=2, max_builders=1)
        self.addCleanup(self.cache.close)

    @staticmethod
    def build(data):
        def write(target):
            target.write(data)
            return 'image/png', '"fixture"'
        return write

    def test_shared_leases_use_independent_offsets_and_do_not_rebuild(self):
        with self.cache.open('same', 4, self.build(b'abcd')) as (first, *_):
            self.assertEqual(first.read(2), b'ab')
            with self.cache.open('same', 4, lambda _: self.fail('hot page rebuilt')) as (second, *_):
                self.assertTrue(second.immutable_snapshot)
                self.assertEqual(second.read(3), b'abc')
                self.assertEqual(first.read(2), b'cd')
                second.seek(-2, 2)
                self.assertEqual(second.read(), b'cd')

    def test_disk_budget_counts_held_entries_and_evicts_inactive_lru(self):
        with self.cache.open('old', 4, self.build(b'old!')):
            pass
        with self.cache.open('held', 4, self.build(b'held')):
            with self.cache.open('new', 4, self.build(b'new!')) as (new, *_):
                self.assertEqual(new.read(), b'new!')
                self.assertEqual(self.cache.snapshot()['bytes'], 8)
                with self.cache.open('over', 1, lambda _: self.fail('over budget')) as denied:
                    self.assertIsNone(denied)
            self.assertNotIn('old', self.cache.entries)

    def test_shutdown_does_not_interrupt_open_snapshot_but_releases_on_exit(self):
        with self.cache.open('held', 4, self.build(b'abcd')) as (held, *_):
            self.cache.close()
            self.assertEqual(self.cache.snapshot()['bytes'], 4)
            self.assertEqual(held.read(), b'abcd')
            with self.cache.open('after', 4, lambda _: self.fail('closed cache rebuilt')) as missed:
                self.assertIsNone(missed)
        self.assertEqual(self.cache.snapshot()['bytes'], 0)

    def test_duplicate_builders_coalesce_and_budget_applies_during_build(self):
        started, resume = threading.Event(), threading.Event()
        calls = []
        def build(target):
            calls.append(1)
            started.set()
            self.assertTrue(resume.wait(3))
            return self.build(b'page')(target)
        def load():
            with self.cache.open('same', 4, build) as (source, *_):
                return source.read()
        with ThreadPoolExecutor(2) as pool:
            first = pool.submit(load)
            try:
                self.assertTrue(started.wait(3))
                second = pool.submit(load)
                self.assertEqual(self.cache.snapshot()['bytes'], 4)
                with self.cache.open('other', 1, lambda _: self.fail('too many builders')) as denied:
                    self.assertIsNone(denied)
            finally:
                resume.set()
            self.assertEqual((first.result(3), second.result(3)), (b'page', b'page'))
        self.assertEqual(calls, [1])

    def test_failed_temporary_storage_backs_off_and_returns_the_budget(self):
        with patch('page_cache.tempfile.TemporaryFile', side_effect=OSError('fixture disk full')) as create:
            for key in ('one', 'two'):
                with self.cache.open(key, 4, lambda _: self.fail('created a cache file')) as missed:
                    self.assertIsNone(missed)
            create.assert_called_once()
        self.assertEqual((self.cache.snapshot()['bytes'], self.cache.snapshot()['entries']), (0, 0))
